        $now = now();

        DB::table('module_library_items')->updateOrInsert(
            ['module_code' => 'BAYESIAN-DATA-ANALYSIS-BASIC-V2'],
            [
                'module_no' => 11,
                'title' => 'Introduction to Bayesian Data Analysis',
                'year_level' => 'Year 2',
                'version_no' => 2,
                'version_name' => 'Introduction to Bayesian Data Analysis Practice and MCQ Review',
                'version_code' => 'V2',
                'description' => 'Bayes\' theorem, prior/posterior distributions, MCMC sampling, and probabilistic inference for real-world data. This version emphasizes code tracing, worked practice, debugging, MCQ reasoning, comparison of methods, and mastery evidence.',
                'estimated_minutes' => 690,
                'sort_order' => 32,
                'is_active' => true,
                'created_at' => $now,
                'updated_at' => $now,
            ]
        );

        DB::table('module_library_items')
            ->where('module_code', 'BAYESIAN-DATA-ANALYSIS-BASIC-V2')
            ->update([
                'content_sections' => json_encode($this->contentSections(), JSON_UNESCAPED_UNICODE),
                'updated_at' => now(),
            ]);

        DB::table('module_library_items')
            ->where('module_code', 'BAYESIAN-DATA-ANALYSIS-BASIC-V2')
            ->update([
                'mcq_questions' => json_encode($this->mcqQuestions(), JSON_UNESCAPED_UNICODE),
